\set ON_ERROR_STOP on
BEGIN;
SELECT test.assert(NOT has_table_privilege('authenticated','public.organization_join_requests','INSERT'), 'no direct request insert');
SELECT test.assert(NOT has_table_privilege('authenticated','public.organization_join_requests','UPDATE'), 'no direct request update');
SELECT test.assert(NOT has_table_privilege('authenticated','public.organization_join_requests','DELETE'), 'no direct request delete');
SET LOCAL ROLE anon;
SELECT test.expect_error('SELECT public.search_joinable_organizations()', '42501','anonymous cannot discover agencies');
SELECT test.expect_error('SELECT * FROM public.organization_join_requests', '42501','anonymous cannot read requests');
SET LOCAL ROLE authenticated;
SELECT test.expect_error('SELECT public.search_joinable_organizations()', '42501','missing identity denied');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
SELECT test.assert(public.search_joinable_organizations()='[]'::jsonb, 'existing agencies private by default');
SELECT test.expect_error($$SELECT public.request_organization_access('10000000-0000-0000-0000-000000000001')$$,'P0001','closed agency rejects request');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
SELECT public.set_organization_discovery('10000000-0000-0000-0000-000000000001',true);
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
SELECT test.assert(jsonb_array_length(public.search_joinable_organizations('Agency'))=1, 'only opted-in agency discoverable');
SELECT test.assert(NOT (public.search_joinable_organizations()->0 ? 'email'), 'directory omits personal data');
SELECT test.assert((SELECT count(*) FROM public.organizations)=0, 'discovery does not open organizations table');
SELECT public.request_organization_access('10000000-0000-0000-0000-000000000001');
SELECT public.request_organization_access('10000000-0000-0000-0000-000000000001');
SELECT test.assert((SELECT count(*) FROM public.organization_join_requests)=1,'duplicate requests idempotent');
SELECT test.assert((SELECT count(*) FROM public.organization_members)=0,'pending request creates no membership');
SELECT test.assert((SELECT count(*) FROM public.clients)=0,'pending request grants no client access');
SELECT test.assert(public.my_organization_join_requests()->0->>'status'='pending','applicant sees waiting status');
SELECT test.expect_error($$SELECT public.review_organization_access((SELECT id FROM public.organization_join_requests LIMIT 1),true)$$,'42501','applicant cannot approve self');
SELECT test.expect_error($$UPDATE public.organization_join_requests SET status='approved'$$,'42501','cannot forge approval');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000005',true);
SELECT test.assert((SELECT count(*) FROM public.organization_join_requests)=0,'other agency owner cannot read requests');
SELECT test.expect_error($$SELECT public.organization_access_review_queue('10000000-0000-0000-0000-000000000001')$$,'42501','other agency owner cannot inspect queue');
SELECT test.expect_error($$SELECT public.set_organization_discovery('10000000-0000-0000-0000-000000000001',true)$$,'42501','other agency owner cannot configure discovery');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
SELECT test.expect_error($$SELECT public.organization_access_review_queue('10000000-0000-0000-0000-000000000001')$$,'42501','editor cannot inspect queue');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
SELECT test.assert(jsonb_array_length(public.organization_access_review_queue('10000000-0000-0000-0000-000000000001')->'requests')=1,'leader sees pending request');
SELECT test.expect_error($$SELECT public.set_organization_discovery('10000000-0000-0000-0000-000000000001',false)$$,'42501','leader cannot change directory visibility');
SELECT public.review_organization_access((SELECT id FROM public.organization_join_requests LIMIT 1),true);
SELECT test.expect_error($$SELECT public.review_organization_access((SELECT id FROM public.organization_join_requests LIMIT 1),true)$$,'P0001','request cannot be approved twice');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
SELECT test.assert(public.get_org_role('10000000-0000-0000-0000-000000000001')='editor','approval grants only collaborator');
SELECT test.assert((SELECT count(*) FROM public.clients)=1,'approved member sees only target agency clients');
SELECT test.assert(public.my_organization_join_requests()->0->>'status'='approved','applicant sees approval');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000006',true);
SELECT test.expect_error($$SELECT public.request_organization_access('10000000-0000-0000-0000-000000000001')$$,'42501','unconfirmed email denied');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000007',true);
SELECT test.expect_error($$SELECT public.request_organization_access('10000000-0000-0000-0000-000000000001')$$,'P0001','suspended user cannot bypass with request');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000008',true);
SELECT public.request_organization_access('10000000-0000-0000-0000-000000000001');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
SELECT public.review_organization_access((SELECT id FROM public.organization_join_requests WHERE user_id='00000000-0000-0000-0000-000000000008'),false);
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000008',true);
SELECT test.assert((SELECT count(*) FROM public.organization_members)=0,'rejection creates no membership');
SELECT test.expect_error($$SELECT public.request_organization_access('10000000-0000-0000-0000-000000000001')$$,'P0001','rejected requests cannot spam resubmissions');
RESET ROLE;
SELECT test.assert((SELECT reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL FROM public.organization_join_requests WHERE user_id='00000000-0000-0000-0000-000000000008'),'decision records reviewer and time');
UPDATE public.organizations SET accepts_join_requests=true;
SET LOCAL ROLE authenticated;
DO $$ BEGIN
  FOR n IN 2..6 LOOP PERFORM public.request_organization_access(('10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid); END LOOP;
END $$;
SELECT test.expect_error($$SELECT public.request_organization_access('10000000-0000-0000-0000-000000000007')$$,'P0001','pending request count is bounded');
RESET ROLE;
-- A separate path (e.g. invite) granted an existing role while the request waited.
UPDATE public.organization_plans SET max_members=4 WHERE code='test';
INSERT INTO public.organization_join_requests(organization_id,user_id) VALUES
 ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002'),
 ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000007');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
SELECT public.review_organization_access((SELECT id FROM public.organization_join_requests WHERE user_id='00000000-0000-0000-0000-000000000002'),true);
SELECT test.assert(public.get_org_role('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002')='manager','approval never downgrades existing leadership');
SELECT test.expect_error($$SELECT public.review_organization_access((SELECT id FROM public.organization_join_requests WHERE user_id='00000000-0000-0000-0000-000000000007'),true)$$,'P0001','old request cannot reactivate suspended member');
SELECT test.assert((SELECT status FROM public.organization_join_requests WHERE user_id='00000000-0000-0000-0000-000000000007')='pending','failed approval leaves request pending atomically');
RESET ROLE;
UPDATE auth.users SET email_confirmed_at=now() WHERE id='00000000-0000-0000-0000-000000000006';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000006',true);
SELECT public.request_organization_access('10000000-0000-0000-0000-000000000001');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
SELECT test.expect_error($$SELECT public.review_organization_access((SELECT id FROM public.organization_join_requests WHERE user_id='00000000-0000-0000-0000-000000000006'),true)$$,'23514','approval respects the existing plan member limit');
SELECT test.assert((SELECT status FROM public.organization_join_requests WHERE user_id='00000000-0000-0000-0000-000000000006')='pending','limit failure does not consume request');
SELECT test.assert(public.get_org_role('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000006') IS NULL,'limit failure grants no access');
ROLLBACK;
